import Quiz from '../models/Quiz.js';
import { generateQuiz } from '../services/aiService.js';

// @desc    Get all quizzes taken or generated by user
// @route   GET /api/quizzes
// @access  Private
export const getQuizzes = async (req, res) => {
  try {
    const quizzes = await Quiz.find({ user: req.user._id }).sort({ createdAt: -1 });
    res.json({ success: true, quizzes });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
};

// @desc    Get single quiz by ID
// @route   GET /api/quizzes/:id
// @access  Private
export const getQuizById = async (req, res) => {
  try {
    const quiz = await Quiz.findOne({ _id: req.params.id, user: req.user._id });
    if (!quiz) {
      return res.status(404).json({ success: false, message: 'Quiz not found' });
    }
    res.json({ success: true, quiz });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
};

// @desc    Generate a new quiz from notes or topic
// @route   POST /api/quizzes/generate
// @access  Private
export const createQuiz = async (req, res) => {
  try {
    const { title, content, numQuestions = 3, difficulty = 'medium' } = req.body;

    if (!title && !content) {
      return res.status(400).json({ success: false, message: 'Please provide study material or a topic title' });
    }

    const quizTitle = title || 'Interactive Study Quiz';
    const validDifficulty = ['easy', 'medium', 'hard'].includes(String(difficulty).toLowerCase())
      ? String(difficulty).toLowerCase()
      : 'medium';

    // Generate questions using AI service
    const questions = await generateQuiz({
      title: quizTitle,
      text: content,
      numQuestions: Number(numQuestions) || 3,
      difficulty: validDifficulty,
    });

    const quiz = await Quiz.create({
      user: req.user._id,
      title: quizTitle,
      difficulty: validDifficulty,
      questions,
      score: 0,
      totalQuestions: questions.length,
    });

    res.status(201).json({ success: true, quiz });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
};

// @desc    Save/update quiz score result
// @route   PUT /api/quizzes/:id/score
// @access  Private
export const updateQuizScore = async (req, res) => {
  try {
    const { score } = req.body;
    const quiz = await Quiz.findOne({ _id: req.params.id, user: req.user._id });

    if (!quiz) {
      return res.status(404).json({ success: false, message: 'Quiz not found' });
    }

    quiz.score = Number(score);
    await quiz.save();

    res.json({ success: true, quiz });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
};

// @desc    Delete a quiz
// @route   DELETE /api/quizzes/:id
// @access  Private
export const deleteQuiz = async (req, res) => {
  try {
    const quiz = await Quiz.findOneAndDelete({ _id: req.params.id, user: req.user._id });
    if (!quiz) {
      return res.status(404).json({ success: false, message: 'Quiz not found' });
    }
    res.json({ success: true, message: 'Quiz deleted successfully' });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
};
